
# ============================================================
# Bulk RNA-seq analysis of IPF fibroblasts treated with siHic-5
# Dataset: GSE248253
#
# Analyses:
#   1. Data normalization and rlog transformation
#   2. Heatmap of the top 2,000 variable genes
#   3. GO Cellular Component (GO-CC) enrichment analysis
#   4. GSEA of TGF-beta signaling, EMT, and ECM-related pathways
#
# Input:
#   countdata.rds
#
# Note:
#   This script starts from the gene count matrix generated by
#   featureCounts. FASTQ quality control, STAR alignment, and
#   featureCounts processing are not included.
# ============================================================


#------------------------------
# 1. Load required packages
#------------------------------

library(DESeq2)
library(pheatmap)
library(matrixStats)
library(clusterProfiler)
library(org.Hs.eg.db)
library(msigdbr)
library(fgsea)
library(ggplot2)
library(dplyr)


#------------------------------
# 2. Load count data
#------------------------------

# Set the working directory
setwd(".")

# Load the gene count matrix
countdata <- readRDS("countdata.rds")

# Rename the siTarget sample
colnames(countdata)[
  colnames(countdata) == "TGFB1_siTarget"
] <- "TGFB1_siHic-5"

# Check sample names
colnames(countdata)

# Check the dimensions of the count matrix
dim(countdata)

# Inspect the count matrix
head(countdata)


#------------------------------
# 3. Prepare sample information
#------------------------------

# Define treatment groups based on sample names
sample_map <- c(
  "mock" = "mock",
  "TGFB1_mock" = "TGFB1_mock",
  "TGFB1_siCNT" = "TGFB1_siCNT",
  "TGFB1_siHic-5" = "TGFB1_siHic-5"
)

samples <- colnames(countdata)

# Check whether all sample names are recognized
if (!all(samples %in% names(sample_map))) {
  stop(
    "Unexpected sample names detected in countdata. ",
    "Please check colnames(countdata)."
  )
}

# Assign treatment groups according to sample names
treatment <- unname(sample_map[samples])

coldata <- data.frame(
  row.names = samples,
  treatment = factor(
    treatment,
    levels = c(
      "mock",
      "TGFB1_mock",
      "TGFB1_siCNT",
      "TGFB1_siHic-5"
    )
  )
)

# Inspect sample information
coldata


#------------------------------
# 4. Data normalization and rlog transformation
#------------------------------

# Create a DESeqDataSet object
dds <- DESeqDataSetFromMatrix(
  countData = countdata,
  colData = coldata,
  design = ~ treatment
)

# Estimate size factors
dds <- estimateSizeFactors(dds)

# Obtain normalized counts
norm_counts <- counts(
  dds,
  normalized = TRUE
)

# Perform regularized log transformation
rld <- rlog(
  dds,
  blind = TRUE
)

rld_mat <- assay(rld)

# Save the rlog-transformed object
saveRDS(
  rld,
  file = "rld.rds"
)


#------------------------------
# 5. Heatmap of the top 2,000 variable genes
#------------------------------

# Define the sample order
sample_order <- c(
  "mock",
  "TGFB1_mock",
  "TGFB1_siCNT",
  "TGFB1_siHic-5"
)

# Set the order of treatment groups
coldata$treatment <- factor(
  coldata$treatment,
  levels = sample_order
)

# Select the 2,000 most variable genes
top_genes <- head(
  order(
    matrixStats::rowVars(rld_mat),
    decreasing = TRUE
  ),
  2000
)

# Generate the heatmap
pheatmap(
  rld_mat[top_genes, sample_order],
  scale = "row",
  annotation_col = coldata,
  cluster_cols = FALSE,
  fontsize_row = 5,
  fontsize_col = 10
)


#------------------------------
# 6. Determine gene identifier type
#------------------------------

# Inspect gene identifiers
gene_ids <- rownames(rld_mat)

# Detect whether gene identifiers are Ensembl IDs or gene symbols
if (all(grepl("^ENSG", gene_ids))) {
  
  gene_id_type <- "ENSEMBL"
  
  # Remove Ensembl version suffixes, if present
  gene_ids_clean <- sub(
    "\\.[0-9]+$",
    "",
    gene_ids
  )
  
  # Check for duplicated identifiers after removing version suffixes
  if (anyDuplicated(gene_ids_clean)) {
    stop(
      "Duplicated Ensembl IDs detected after removing version suffixes. ",
      "Please resolve duplicated identifiers before proceeding."
    )
  }
  
  # Use Ensembl gene identifiers for GSEA
  gsea_gene_column <- "ensembl_gene"
  
} else if (!any(grepl("^ENSG", gene_ids))) {
  
  gene_id_type <- "SYMBOL"
  
  gene_ids_clean <- gene_ids
  
  # Use gene symbols for GSEA
  gsea_gene_column <- "gene_symbol"
  
} else {
  
  stop(
    "Mixed or unsupported gene identifier types detected. ",
    "Please check rownames(rld_mat)."
  )
}

# Update row names for downstream analyses
rownames(rld_mat) <- gene_ids_clean

# Check the identifier type
gene_id_type


#------------------------------
# 7. GO Cellular Component (GO-CC) enrichment analysis
#------------------------------

# Define the fold-change threshold
threshold <- log2(1.5)

# Calculate expression differences between siHic-5 and siCNT
fc_siHic5_vs_siCNT <-
  rld_mat[, "TGFB1_siHic-5"] -
  rld_mat[, "TGFB1_siCNT"]

# Select genes with an absolute expression difference greater than the threshold
genes_siHic5_change <- names(fc_siHic5_vs_siCNT)[
  abs(fc_siHic5_vs_siCNT) > threshold
]

# Convert target genes to Entrez IDs
target.df <- bitr(
  genes_siHic5_change,
  fromType = gene_id_type,
  toType = "ENTREZID",
  OrgDb = org.Hs.eg.db
)

target_entrez <- unique(target.df$ENTREZID)

# Define the background gene set using all genes included in the rlog matrix
all_genes <- rownames(rld_mat)

bg.df <- bitr(
  all_genes,
  fromType = gene_id_type,
  toType = "ENTREZID",
  OrgDb = org.Hs.eg.db
)

# Check the number of mapped genes
length(target_entrez)
length(unique(bg.df$ENTREZID))

# Perform GO Cellular Component enrichment analysis
egoCC <- enrichGO(
  gene = target_entrez,
  universe = unique(bg.df$ENTREZID),
  OrgDb = org.Hs.eg.db,
  ont = "CC",
  pAdjustMethod = "BH",
  pvalueCutoff = 0.05,
  readable = TRUE
)

# Inspect the enrichment results
head(egoCC)

# Visualize the top 20 enriched GO-CC terms
p <- dotplot(
  egoCC,
  showCategory = 20
) +
  theme(
    axis.text.y = element_text(size = 8),
    axis.text.x = element_text(size = 10),
    axis.title = element_text(size = 10)
  )

p


#------------------------------
# 8. Calculate log2 fold changes for GSEA
#------------------------------

# Estimate size factors using DESeq2
dds <- DESeqDataSetFromMatrix(
  countData = countdata,
  colData = coldata,
  design = ~ treatment
)

dds <- estimateSizeFactors(dds)

norm_counts <- counts(
  dds,
  normalized = TRUE
)

# Calculate mean normalized counts for each group
mean_siCNT <- rowMeans(
  norm_counts[
    ,
    coldata$treatment == "TGFB1_siCNT",
    drop = FALSE
  ]
)

mean_siHic5 <- rowMeans(
  norm_counts[
    ,
    coldata$treatment == "TGFB1_siHic-5",
    drop = FALSE
  ]
)

# Calculate log2 fold changes
log2FC <- log2(
  (mean_siHic5 + 1) /
    (mean_siCNT + 1)
)

# Generate a ranked gene list
gene_rank <- sort(
  log2FC,
  decreasing = TRUE
)

# Assign gene identifiers to the ranked list
names(gene_rank) <- rownames(rld_mat)

# Remove genes with missing or duplicated identifiers
gene_rank <- gene_rank[
  !is.na(names(gene_rank)) &
    names(gene_rank) != ""
]

if (anyDuplicated(names(gene_rank))) {
  stop(
    "Duplicated gene identifiers detected in the ranked gene list."
  )
}


#------------------------------
# 9. GSEA using Hallmark gene sets
#------------------------------

# Retrieve Hallmark gene sets
msig_h <- msigdbr(
  species = "Homo sapiens",
  category = "H"
)

# Extract the TGF-beta signaling gene set
tgf_geneset <- msig_h[
  msig_h$gs_name == "HALLMARK_TGF_BETA_SIGNALING",
]

tgf_list <- list(
  HALLMARK_TGF_BETA_SIGNALING =
    unique(tgf_geneset[[gsea_gene_column]])
)

# Remove missing identifiers
tgf_list[[1]] <- tgf_list[[1]][
  !is.na(tgf_list[[1]]) &
    tgf_list[[1]] != ""
]

# Perform GSEA
fgseaRes <- fgsea(
  pathways = tgf_list,
  stats = gene_rank,
  minSize = 15,
  maxSize = 500
)

# Inspect the results
fgseaRes

# Calculate the proportion of leading-edge genes
leading_edge_n <- length(
  fgseaRes$leadingEdge[[1]]
)

pathway_n <- length(
  tgf_list[[1]]
)

leading_edge_n / pathway_n

# Extract normalized enrichment score and P-values
fgseaRes[, c("NES", "pval", "padj")]


#------------------------------
# 10. GSEA enrichment plot for TGF-beta signaling
#------------------------------

# Calculate leading-edge percentage
leading_edge_percent <- 100 *
  leading_edge_n / pathway_n

# Generate the enrichment plot
p <- plotEnrichment(
  tgf_list[[1]],
  gene_rank
) +
  labs(
    title = "HALLMARK_TGF_BETA_SIGNALING",
    subtitle = sprintf(
      "NES = %.2f, leading edge = %.0f%%",
      fgseaRes$NES[1],
      leading_edge_percent
    ),
    x = "Rank in ordered gene list",
    y = "Running enrichment score"
  ) +
  theme_classic(base_size = 16) +
  theme(
    plot.title = element_text(
      size = 18,
      face = "bold"
    ),
    plot.subtitle = element_text(size = 14),
    axis.title = element_text(size = 16),
    axis.text = element_text(size = 14),
    panel.border = element_rect(
      color = "black",
      fill = NA
    )
  )

p


#------------------------------
# 11. GSEA for EMT and ECM-related gene sets
#------------------------------

# Extract the Hallmark EMT gene set
emt_geneset <- msig_h[
  msig_h$gs_name ==
    "HALLMARK_EPITHELIAL_MESENCHYMAL_TRANSITION",
]

emt_list <- list(
  HALLMARK_EMT =
    unique(emt_geneset[[gsea_gene_column]])
)

# Remove missing identifiers
emt_list[[1]] <- emt_list[[1]][
  !is.na(emt_list[[1]]) &
    emt_list[[1]] != ""
]

# Check the number of overlapping genes
sum(names(gene_rank) %in% emt_list[[1]])

# Perform GSEA for EMT
fgsea_emt <- fgsea(
  pathways = emt_list,
  stats = gene_rank,
  minSize = 10,
  maxSize = 500
)

fgsea_emt


# Retrieve GO Biological Process gene sets from MSigDB C5
msig_c5 <- msigdbr(
  species = "Homo sapiens",
  category = "C5",
  subcategory = "GO:BP"
)

# Identify ECM-related gene sets
unique(
  msig_c5$gs_name[
    grep(
      "EXTRACELLULAR_MATRIX",
      msig_c5$gs_name
    )
  ]
)

# Extract positive and negative regulation of ECM organization
pos_ecm <- msig_c5[
  msig_c5$gs_name ==
    "GOBP_POSITIVE_REGULATION_OF_EXTRACELLULAR_MATRIX_ORGANIZATION",
]

neg_ecm <- msig_c5[
  msig_c5$gs_name ==
    "GOBP_NEGATIVE_REGULATION_OF_EXTRACELLULAR_MATRIX_ORGANIZATION",
]

ecm_list <- list(
  ECM_Positive = unique(pos_ecm[[gsea_gene_column]]),
  ECM_Negative = unique(neg_ecm[[gsea_gene_column]])
)

ecmP_list <- list(
  ECM_Positive = unique(pos_ecm[[gsea_gene_column]])
)

ecmN_list <- list(
  ECM_Negative = unique(neg_ecm[[gsea_gene_column]])
)

# Remove missing identifiers
ecm_list <- lapply(
  ecm_list,
  function(x) {
    x[!is.na(x) & x != ""]
  }
)

ecmP_list <- lapply(
  ecmP_list,
  function(x) {
    x[!is.na(x) & x != ""]
  }
)

ecmN_list <- lapply(
  ecmN_list,
  function(x) {
    x[!is.na(x) & x != ""]
  }
)

# Check the number of overlapping genes
sum(names(gene_rank) %in% ecm_list[[1]])

# Perform GSEA for ECM-related gene sets
fgsea_ecm <- fgsea(
  pathways = ecm_list,
  stats = gene_rank,
  minSize = 10
)

fgsea_ecm


#------------------------------
# 12. Comparison of NES across selected pathways
#------------------------------

# Combine the selected pathways
all_pathways <- list(
  TGFb = tgf_list[[1]],
  EMT = emt_list[[1]],
  ECM_Positive = ecmP_list[[1]],
  ECM_Negative = ecmN_list[[1]]
)

# Perform GSEA for all selected pathways
fgsea_all <- fgsea(
  pathways = all_pathways,
  stats = gene_rank,
  minSize = 10
)

# Inspect the results
fgsea_all[, c("pathway", "NES", "pval")]

# Prepare data for visualization
df <- as.data.frame(fgsea_all) %>%
  select(pathway, NES) %>%
  rename(Pathway = pathway)

# Set the pathway order
df$Pathway <- factor(
  df$Pathway,
  levels = c(
    "TGFb",
    "EMT",
    "ECM_Positive",
    "ECM_Negative"
  )
)

# Generate the NES comparison plot
ggplot(
  df,
  aes(x = NES, y = Pathway)
) +
  geom_bar(
    stat = "identity",
    fill = "gray30"
  ) +
  geom_vline(
    xintercept = 0,
    linetype = "dashed"
  ) +
  geom_text(
    aes(label = round(NES, 2)),
    hjust = ifelse(df$NES > 0, -0.2, 1.2),
    size = 5
  ) +
  scale_x_continuous(
    limits = c(-2.0, 1.2)
  ) +
  labs(
    title = "Gene Set Enrichment Analysis (pooled RNA-seq)",
    subtitle = "Directional enrichment only (no statistical inference)",
    x = "Normalized Enrichment Score (NES)",
    y = NULL
  ) +
  theme_classic(base_size = 16)


#------------------------------
# 13. Session information
#------------------------------

sessionInfo()
